 function refresh(){let [name,icon,title,desc]=trails[activeTrail],need=3,found=[0,1,2].filter(j=>bells.has(`${activeTrail}-${j}`)).length;$('#questEyebrow').textContent=`TRAIL ${String(activeTrail+1).padStart(2,'0')} · ${name.toUpperCase()}`;$('#questTitle').textContent=completed.has(activeTrail)?'Trail restored!':title;$('#questText').textContent=completed.has(activeTrail)?'Beautiful work, Brinco. The Starbells are singing again!':desc+` Find ${need} Starbells, then return to the trail marker.`;$('#questFoot').textContent=completed.has(activeTrail)?'Mission complete':`${found} / 3 Starbells`;$('#questProgress').style.width=`${completed.has(activeTrail)?100:found/3*100}%`;$('#boneCount').textContent=bones.size;$('#bellCount').textContent=bells.size;$('#xpCount').textContent=xp;$('#levelCount').textContent=1+Math.floor(xp/100);$('#powerCount').textContent=1+upgrades;}
 function checkPickup(){for(const [id,o]of pickups){if(bells.has(id)){o.visible=false;continue}o.visible=true;if(dog.position.distanceTo(o.position)<1.9){bells.add(id);xp+=10;o.visible=false;showToast('Starbell found! +10 XP 🔔');refresh();save()}}for(const[id,o]of boneItems){if(bones.has(id)){o.visible=false;continue}o.visible=true;if(dog.position.distanceTo(o.position)<1.6){bones.add(id);xp+=5;o.visible=false;showToast('A tasty trail treat! +5 XP 🦴');refresh();save()}}}
 function interactNow(){if(!gameStarted)return;let b=beacons[activeTrail];if(dog.position.distanceTo(b.pos)<5){let found=[0,1,2].filter(j=>bells.has(`${activeTrail}-${j}`)).length;if(found<3){showToast(`The marker needs ${3-found} more Starbell${3-found===1?'':'s'} ✨`)}else if(!completed.has(activeTrail)){completed.add(activeTrail);xp+=40;showToast(`Trail ${activeTrail+1} restored! +40 XP 🌟`);if(activeTrail<14){activeTrail++;showToast('New trail unlocked: '+trails[activeTrail][0]+'!')}else showToast('You did it! The Skybell Summit sings! 🏔️');refresh();save()}else showToast('This trail is already singing!')}else if(dog.position.distanceTo(sheep.position)<4){openSheep()}else if(dog.position.distanceTo(ball.position)<4){startFetch()}else{showToast('Sniff around for Starbells, treats, and friends!')}}

